suppressPackageStartupMessages(library(limma))
O<-'/mnt/BioDisk/wangmingyuan/GI_preanalysis_20260923/CRC_routes_v1/deep_v2';R<-file.path(O,'results/second_validation');E<-as.matrix(read.delim(gzfile(file.path(R,'gene_expression.tsv.gz')),row.names=1,check.names=FALSE));m<-read.delim(file.path(R,'design.tsv'),check.names=FALSE);map<-read.delim(file.path(O,'metadata/candidate_symbol_map.tsv'),check.names=FALSE);rownames(E)<-as.character(rownames(E));stopifnot(all(is.finite(E)),nrow(map)==126)
m$strict_colon<-m$strict_colon%in%c('True','TRUE');sets<-list(hepatic=c('ALB','FGA','FGB','FGG','APOA1','APOA2','TTR','HP','AGT','GC','CRP'),stromal=c('COL1A1','COL1A2','DCN','LUM'),epithelial=c('EPCAM','KRT8','KRT18','KRT19'));cov<-data.frame();for(n in names(sets)){hit<-intersect(sets[[n]],rownames(E));stopifnot(length(hit)>=.7*length(sets[[n]]));m[[n]]<-colMeans(E[hit,m$sample,drop=FALSE]);cov<-rbind(cov,data.frame(proxy=n,measured=paste(hit,collapse=';'),missing=paste(setdiff(sets[[n]],hit),collapse=';')))};write.table(cov,file.path(R,'proxy_coverage.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
writeLines(c('Second independent cohort GSE14297; author VST+spline normalized intensity, no re-log. Unique direct symbols/RefSeq/NCBI synonyms; multi-probe average without outcome selection.','Primary analysis13 strict-colon pairs, all18 CRC sensitivity. Paired limma on all mapped complete genes; genomewide and fixed126 family BH each. Colon primary, composition and hepatic sensitivities preserved. Normal-liver5 controls descriptive only.'),file.path(R,'MODEL_PLAN.txt'))
output<-list();diags<-data.frame();for(label in c('colon_main','CRC_all18','colon_composition','colon_hepatic')){
 z<-m[m$site%in%c('PT','LM')&(if(label=='CRC_all18') TRUE else m$strict_colon),];z$patient<-factor(z$patient);z$site<-factor(z$site,levels=c('PT','LM'));f<-if(label=='colon_composition') ~patient+stromal+epithelial+site else if(label=='colon_hepatic') ~patient+hepatic+site else ~patient+site;d<-model.matrix(f,z);stopifnot(qr(d)$rank==ncol(d));fit<-eBayes(lmFit(E[,z$sample],d));t<-topTable(fit,coef='siteLM',number=Inf,sort.by='none',confint=TRUE);t$gene<-rownames(t);write.table(t,gzfile(file.path(R,paste0(label,'_all_genes.tsv.gz'))),sep='\t',quote=FALSE,row.names=FALSE);v<-merge(map,t,by.x='canonical',by.y='gene',all.x=TRUE,sort=FALSE);pp<-v$P.Value;pp[is.na(pp)]<-1;v$FDR_fixed126<-p.adjust(pp,'BH');v$FDR_fixed126[is.na(v$P.Value)]<-NA;v$model<-label;v$n_pairs<-length(levels(z$patient));output[[label]]<-v;diags<-rbind(diags,data.frame(model=label,pairs=length(levels(z$patient)),genes=nrow(E),rank=qr(d)$rank))
}
x<-do.call(rbind,output);write.table(x,file.path(R,'candidate_validation_all_models.tsv'),sep='\t',quote=FALSE,row.names=FALSE);write.table(diags,file.path(R,'model_diagnostics.tsv'),sep='\t',quote=FALSE,row.names=FALSE);vals<-data.frame();for(g in c('CGNL1','CREB3L1','PCSK5','SLC9B2')){if(g%in%rownames(E))vals<-rbind(vals,data.frame(gene=g,m,expression=E[g,m$sample]))};write.table(vals,file.path(R,'focused_sample_values.tsv'),sep='\t',quote=FALSE,row.names=FALSE);writeLines('exit_code=0; colon_pairs=13; CRC_pairs=18; fixed_family=126; normal_liver5_descriptive',file.path(R,'COMPLETE.txt'));print(as.data.frame(x[x$candidate%in%c('CGNL1','CREB3L1','PCSK5','SLC9B2'),c('candidate','model','n_pairs','logFC','CI.L','CI.R','P.Value','adj.P.Val','FDR_fixed126')]));print(diags)
